def brace(s):return str(s).replace('\\','\\textbackslash{}').replace('{','\\{').replace('}','\\}')
out=[]
for b in records:
 out.append('@'+b['entry_type']+'{'+b['key']+',\n'+''.join('  '+k+' = {'+brace(v)+'},\n' for k,v in b.items() if k not in ('key','entry_type'))+'}\n')
